package chiselFv

import chisel3.experimental.SourceInfo
import chisel3._
import chisel3.ltl.AssertProperty
import chisel3.util.Cat
import chisel3.util.PopCount
import chisel3.util.log2Ceil


trait Formal {
  this: Module => 

  private val resetCounter = Module(new ResetCounter)
  resetCounter.io.clk := this.clock
  resetCounter.io.reset := this.reset.asBool
  val timeSinceReset = resetCounter.io.timeSinceReset
  val notChaos = resetCounter.io.notChaos

  private val DefaultLivenessBound = 64

  private def requireNonNegative(value: Int, name: String): Unit = {
    require(value >= 0, s"$name must be non-negative")
  }

  private def requirePositive(value: Int, name: String): Unit = {
    require(value > 0, s"$name must be positive")
  }

  private def counterWidth(maxValue: Int): Int = {
    math.max(1, log2Ceil(maxValue + 2))
  }

  private def delayedBool(cond: Bool, n: Int, sticky: Boolean): Bool = {
    requirePositive(n, "n")

    val pipe = RegInit(0.U(n.W))
    val nextIn = if (sticky) {
      pipe(0) || cond
    } else {
      cond
    }
    val nextPipe = if (n == 1) {
      nextIn.asUInt
    } else {
      Cat(pipe(n - 2, 0), nextIn)
    }

    when(!notChaos) {
      pipe := 0.U
    }.otherwise {
      pipe := nextPipe
    }

    pipe(n - 1)
  }

  private def assertBoundedResponse(req: Bool, resp: Bool, n: Int, msg: String)
                                   (implicit sourceInfo: SourceInfo): Unit = {
    requireNonNegative(n, "n")

    val pending = RegInit(false.B)
    val timer = RegInit(0.U(counterWidth(n).W))
    val nextPending = notChaos && !resp && (pending || req)
    val nextTimer = Mux(pending && !resp, timer + 1.U, 0.U)

    pending := nextPending
    timer := Mux(nextPending, nextTimer, 0.U)

    fvAssert(!nextPending || nextTimer <= n.U, msg)
  }

  def fvAssert(cond: Bool, msg: String = "")
              (implicit sourceInfo: SourceInfo): Unit = {
    when(notChaos) {
      AssertProperty(cond, msg)
    }
  }

  def assertAt(n: UInt, cond: Bool, msg: String = "")
              (implicit sourceInfo: SourceInfo): Unit = {
    when(timeSinceReset === n) {
      fvAssert(cond, msg)
    }
  }

  def assertAfterNStepWhen(cond: Bool, n: Int, asert: Bool, msg: String = "")
                          (implicit sourceInfo: SourceInfo): Unit = {
    when(delayedBool(cond && notChaos, n, sticky = false)) {
      fvAssert(asert, msg)
    }
  }

  def assertNextStepWhen(cond: Bool, asert: Bool, msg: String = "")
                        (implicit sourceInfo: SourceInfo): Unit = {
    assertAfterNStepWhen(cond, 1, asert, msg)
  }

  def assertAlwaysAfterNStepWhen(cond: Bool, n: Int, asert: Bool, msg: String = "")
                                (implicit sourceInfo: SourceInfo): Unit = {
    when(delayedBool(cond && notChaos, n, sticky = true)) {
      fvAssert(asert, msg)
    }
  }

  def past[T <: Data](value: T, n: Int)(block: T => Any)
                     (implicit sourceInfo: SourceInfo): Unit = {
    requireNonNegative(n, "n")

    when(notChaos && timeSinceReset >= n.U) {
      block(Delay(value, n))
    }
  }

  def initialReg(w: Int, v: Int): InitialReg = {
    val reg = Module(new InitialReg(w, v))
    reg.io.clk := clock
    reg.io.reset := reset.asBool
    reg
  }

  def anyconst(w: Int): UInt = {
    val cst = Module(new AnyConst(w))
    cst.io.out
  }

  def astLiveness(req: Bool, resp: Bool)(implicit sourceInfo: SourceInfo): Unit = {
    astLiveness(req, resp, DefaultLivenessBound, "")
  }

  def astLiveness(req: Bool, resp: Bool, msg: String)(implicit sourceInfo: SourceInfo): Unit = {
    astLiveness(req, resp, DefaultLivenessBound, msg)
  }

  def astLiveness(req: Bool, resp: Bool, n: Int)(implicit sourceInfo: SourceInfo): Unit = {
    astLiveness(req, resp, n, "")
  }

  def astLiveness(req: Bool, resp: Bool, n: Int, msg: String)
                 (implicit sourceInfo: SourceInfo): Unit = {
    assertBoundedResponse(req, resp, n, msg)
  }

  def astRelaxedLiveness(req: Bool, resp: Bool, n: Int, msg: String = "")
                        (implicit sourceInfo: SourceInfo): Unit = {
    assertBoundedResponse(req, resp, n, msg)
  }

  def assertLivenessTimer(cond: Bool, reset: Bool, n: Int, msg: String = "")
                         (implicit sourceInfo: SourceInfo): Unit = {
    requireNonNegative(n, "n")

    val timer = RegInit(0.U(counterWidth(n).W))
    val nextTimer = Mux(!notChaos || reset, 0.U, Mux(cond, timer + 1.U, timer))

    timer := nextTimer
    fvAssert(nextTimer <= n.U, msg)
  }

  def assertMutex(conds: Seq[Bool], msg: String = "")
                 (implicit sourceInfo: SourceInfo): Unit = {
    val atMostOne = if (conds.lengthCompare(2) < 0) {
      true.B
    } else {
      PopCount(conds) <= 1.U
    }

    fvAssert(atMostOne, msg)
  }

  def assertOneHot(signal: UInt, msg: String = "")
                  (implicit sourceInfo: SourceInfo): Unit = {
    fvAssert(PopCount(signal) === 1.U, msg)
  }

  def assertOneHot0(signal: UInt, msg: String = "")
                   (implicit sourceInfo: SourceInfo): Unit = {
    fvAssert(PopCount(signal) <= 1.U, msg)
  }

  def assertStable[T <: Data](signal: T, msg: String = "")
                             (implicit sourceInfo: SourceInfo): Unit = {
    past(signal, 1) { previous =>
      fvAssert(signal === previous, msg)
    }
  }

  def assertStableWhen[T <: Data](en: Bool, signal: T, msg: String = "")
                                 (implicit sourceInfo: SourceInfo): Unit = {
    past(signal, 1) { previous =>
      fvAssert(!en || signal === previous, msg)
    }
  }

  def assertOnRise(signal: Bool, cond: Bool, msg: String = "")
                  (implicit sourceInfo: SourceInfo): Unit = {
    past(signal, 1) { previous =>
      fvAssert(!(signal && !previous) || cond, msg)
    }
  }

  def assertOnFall(signal: Bool, cond: Bool, msg: String = "")
                  (implicit sourceInfo: SourceInfo): Unit = {
    past(signal, 1) { previous =>
      fvAssert(!(!signal && previous) || cond, msg)
    }
  }

  def assertImplies(antecedent: Bool, consequent: Bool, msg: String = "")
                   (implicit sourceInfo: SourceInfo): Unit = {
    fvAssert(!antecedent || consequent, msg)
  }

  def assertImpliesDelay(antecedent: Bool, consequent: Bool, n: Int, msg: String = "")
                        (implicit sourceInfo: SourceInfo): Unit = {
    requireNonNegative(n, "n")

    if (n == 0) {
      assertImplies(antecedent, consequent, msg)
    } else {
      when(delayedBool(antecedent && notChaos, n, sticky = false)) {
        fvAssert(consequent, msg)
      }
    }
  }
}

package llmverify

import chisel3._
import chisel3.util._
import chiselFv._

class controlvis extends Module with Formal {
  val io = IO(new Bundle {
    val Rst_n = Input(Bool())
    val WorkMAU = Input(Bool())
    val AccessMode = Input(UInt(2.W))
    val Match = Input(Bool())
    val Valid = Input(Bool())
    val ReadDoneFromBCU_n = Input(Bool())
    val WriteDoneFromBCU_n = Input(Bool())

    val Write = Output(Bool())
    val BCURequest_n = Output(Bool())
    val BCUWriteRequest_n = Output(Bool())
    val BCUDataOE = Output(Bool())
    val CacheDataSelect = Output(Bool())
    val MAUNotReady_n = Output(Bool())

    // Debug outputs to preserve internal signals
    val State = Output(UInt(3.W))
    val Vector = Output(UInt(6.W))
  })

  // State definitions using object with UInt values
  object State {
    val IDLE = 0.U(3.W)
    val READ_HIT = 1.U(3.W)
    val READ_MISS = 2.U(3.W)
    val READ_DATA = 3.U(3.W)
    val WRITE_HIT = 4.U(3.W)
    val WRITE_MISS = 5.U(3.W)
  }

  // State register
  val stateReg = RegInit(State.IDLE)

  // Input registers (synchronized)
  val rRst_n = RegNext(io.Rst_n, false.B)
  val rWorkMAU = RegNext(io.WorkMAU, false.B)
  val rAccessMode = RegNext(io.AccessMode, 0.U)
  val rMatch = RegNext(io.Match, false.B)
  val rValid = RegNext(io.Valid, false.B)
  val rReadDoneFromBCU_n = RegNext(io.ReadDoneFromBCU_n, false.B)
  val rWriteDoneFromBCU_n = RegNext(io.WriteDoneFromBCU_n, false.B)

  // Vector register for combinatorial logic - use RegInit to ensure initialization
  val vector = RegInit("b011001".U(6.W))

  // State machine logic
  when(!io.Rst_n) {
    stateReg := State.IDLE
  }.otherwise {
    switch(stateReg) {
      is(State.IDLE) {
        when(rWorkMAU) {
          when(rAccessMode(0)) { // write
            when(rValid && rMatch) { // write hit
              stateReg := State.WRITE_HIT
            }.otherwise { // write miss
              stateReg := State.WRITE_MISS
            }
          }.elsewhen(!rAccessMode(0)) { // read
            when(rValid && rMatch) { // read hit
              stateReg := State.READ_HIT
            }.otherwise { // read miss
              stateReg := State.READ_MISS
            }
          }
        }
      }
      is(State.READ_HIT) {
        stateReg := State.IDLE
      }
      is(State.READ_MISS) {
        when(!rReadDoneFromBCU_n) { // data is ready
          stateReg := State.READ_DATA // update cache
        }
      }
      is(State.READ_DATA) {
        stateReg := State.IDLE
      }
      is(State.WRITE_HIT) {
        when(!rWriteDoneFromBCU_n) {
          stateReg := State.IDLE
        }
      }
      is(State.WRITE_MISS) {
        when(!rWriteDoneFromBCU_n) {
          stateReg := State.IDLE
        }
      }
    }
  }

  // Combinatorial logic for vector assignment using when/elsewhen/otherwise
  // This ensures all cases are covered
  when(stateReg === State.IDLE) {
    vector := "b011001".U
  }.elsewhen(stateReg === State.READ_HIT) {
    vector := "b011000".U
  }.elsewhen(stateReg === State.READ_MISS) {
    vector := "b001000".U
  }.elsewhen(stateReg === State.READ_DATA) {
    vector := "b111010".U
  }.elsewhen(stateReg === State.WRITE_HIT) {
    vector := "b110100".U
  }.elsewhen(stateReg === State.WRITE_MISS) {
    vector := "b010100".U
  }.otherwise {
    vector := "b011001".U // default to IDLE value
  }

  // Output assignments
  io.Write := vector(5)
  io.BCURequest_n := vector(4)
  io.BCUWriteRequest_n := vector(3)
  io.BCUDataOE := vector(2)
  io.CacheDataSelect := vector(1)
  io.MAUNotReady_n := vector(0)

  // Debug outputs
  io.State := stateReg
  io.Vector := vector

  // =====================================================
  // Formal Verification Assertions
  // =====================================================

  // Safety: stateReg must always be one of the six defined states (0-5).
  // Illegal values 6 and 7 indicate an encoding violation.
  fvAssert(
    stateReg === State.IDLE    || stateReg === State.READ_HIT  ||
    stateReg === State.READ_MISS || stateReg === State.READ_DATA ||
    stateReg === State.WRITE_HIT || stateReg === State.WRITE_MISS,
    "state_encoding_valid"
  )

  // Structural: READ_HIT unconditionally transitions to IDLE in the next cycle.
  assertNextStepWhen(stateReg === State.READ_HIT, stateReg === State.IDLE,
    "read_hit_to_idle")

  // Structural: READ_DATA unconditionally transitions to IDLE in the next cycle.
  assertNextStepWhen(stateReg === State.READ_DATA, stateReg === State.IDLE,
    "read_data_to_idle")

  // Correctness: when in READ_MISS and the BCU signals read data ready
  // (!rReadDoneFromBCU_n asserted, active low), the next state is READ_DATA,
  // not IDLE or anything else.
  assertNextStepWhen(stateReg === State.READ_MISS && !rReadDoneFromBCU_n,
    stateReg === State.READ_DATA,
    "read_miss_to_read_data_on_done")

  // Correctness: when in WRITE_HIT and the BCU signals write done
  // (!rWriteDoneFromBCU_n asserted, active low), the next state is IDLE.
  assertNextStepWhen(stateReg === State.WRITE_HIT && !rWriteDoneFromBCU_n,
    stateReg === State.IDLE,
    "write_hit_to_idle_on_done")

  // Correctness: when in WRITE_MISS and the BCU signals write done,
  // the next state is IDLE.
  assertNextStepWhen(stateReg === State.WRITE_MISS && !rWriteDoneFromBCU_n,
    stateReg === State.IDLE,
    "write_miss_to_idle_on_done")

  // Bounded liveness / progress: once the state machine leaves IDLE,
  // it must return to IDLE within a bounded number of cycles.
  // This catches deadlocks, stuck FSMs, or lost responses.
  astRelaxedLiveness(stateReg =/= State.IDLE, stateReg === State.IDLE,
    50, "return_to_idle_bounded")
}

object VerilogGenerator extends App {
  emitVerilog(new controlvis(), args)
}
